<section class="card"><h2>Pengguna sekolah</h2><p class="muted">Gunakan akun bendahara dan pemeriksa yang berbeda untuk persetujuan LPJ.</p><?php $__currentLoopData = $users; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $u): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><details><summary><?php echo e($u->name); ?> · <?php echo e($u->role); ?> · <?php echo e($u->is_active?'Aktif':'Nonaktif'); ?></summary><p><?php echo e($u->email); ?></p><?php if($u->id!==auth()->id()): ?><form method="post" action="<?php echo e(route('v3.accounts.update',$u->id)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('PATCH'); ?><div class="grid"><label>Peran<select name="role"><?php $__currentLoopData = ['admin','bendahara','kepala_sekolah','user']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $role): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if($u->role===$role): echo 'selected'; endif; ?>><?php echo e($role); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label>Status<select name="is_active"><option value="1" <?php if($u->is_active): echo 'selected'; endif; ?>>Aktif</option><option value="0" <?php if(!$u->is_active): echo 'selected'; endif; ?>>Nonaktif</option></select></label><label>Kata sandi baru (opsional)<input type="password" name="password" minlength="8" autocomplete="new-password"></label><label>Ulangi kata sandi baru<input type="password" name="password_confirmation" autocomplete="new-password"></label></div><p><button>Simpan perubahan</button></p></form><?php else: ?><p class="muted">Akun yang sedang digunakan. Ganti kata sandi melalui Pengaturan sekolah.</p><?php endif; ?></details><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></section>
<section class="card"><h2>Tambah pengguna</h2><form method="post" action="<?php echo e(route('v3.accounts.save')); ?>"><?php echo csrf_field(); ?><div class="grid"><label>Nama<input name="name" required value="<?php echo e(old('name')); ?>" maxlength="255"></label><label>Email<input type="email" name="email" required value="<?php echo e(old('email')); ?>" maxlength="255"></label><label>Peran<select name="role"><?php $__currentLoopData = ['bendahara','kepala_sekolah','user','admin']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $role): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if(old('role')===$role): echo 'selected'; endif; ?>><?php echo e($role); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label>Kata sandi<input type="password" name="password" minlength="8" required autocomplete="new-password"></label><label>Ulangi kata sandi<input type="password" name="password_confirmation" required autocomplete="new-password"></label></div><p><button>Buat akun</button></p></form></section>
